package detector

import (
    "crypto/sha256"
    "embed"
    "encoding/hex"
    "fmt"
    "io/fs"
    "os"
    "path/filepath"
    "strings"

    "github.com/yetone/magpie/internal/plugin"
    "github.com/yetone/magpie/internal/settings"
)

// All runtime code and reference data ship inside the fork's executable.
// The two large reference files are generated by the release preparation step.
//go:embed index.js package.json page/* shared/* data
var bundle embed.FS

// Ensure unpacks an immutable version of the plugin and registers it in the
// existing Bun plugin list. No npm, network access or external CLI is needed
// on the user's machine. An explicit user removal is never undone.
func Ensure() error {
    for _, name := range []string{"data/unified_bank.json", "data/shared_detector.bin"} {
        b, err := bundle.ReadFile(name)
        if err != nil || len(b) < 1<<20 {
            return fmt.Errorf("LM Detector was built without %s; run node .github/scripts/prepare-lm-detector.mjs before go build", name)
        }
    }
    root := filepath.Join(settings.Dir(), "bundled", "lm-detector")
    target, err := materialize(bundle, root)
    if err != nil {
        return err
    }
    return plugin.EnsureBundled(target, "magpie-lm-detector", filepath.Join(root, ".registered"))
}

// materialize never modifies an already-published directory. Versioned paths
// let an older Bun host finish with the old scripts across app upgrades, and
// prevent a failed extraction from corrupting a working installation.
func materialize(files fs.FS, root string) (string, error) {
    sum := sha256.New()
    if err := fs.WalkDir(files, ".", func(name string, entry fs.DirEntry, err error) error {
        if err != nil { return err }
        if entry.IsDir() { return nil }
        b, err := fs.ReadFile(files, name)
        if err != nil { return err }
        sum.Write([]byte(name))
        sum.Write([]byte{0})
        sum.Write(b)
        return nil
    }); err != nil { return "", err }
    version := hex.EncodeToString(sum.Sum(nil))[:20]
    target := filepath.Join(root, version)
    if _, err := os.Stat(filepath.Join(target, ".complete")); err == nil {
        return target, nil
    } else if !os.IsNotExist(err) {
        return "", err
    }
    if err := os.MkdirAll(root, 0o700); err != nil { return "", err }
    stage, err := os.MkdirTemp(root, ".staging-")
    if err != nil { return "", err }
    defer os.RemoveAll(stage)
    if err := fs.WalkDir(files, ".", func(name string, entry fs.DirEntry, err error) error {
        if err != nil { return err }
        if name == "." { return nil }
        // embed.FS contains only checked-in/generated regular files.
        if entry.Type() & os.ModeSymlink != 0 || strings.Contains(name, "..") {
            return fmt.Errorf("invalid embedded LM Detector path: %s", name)
        }
        dest := filepath.Join(stage, filepath.FromSlash(name))
        if entry.IsDir() { return os.MkdirAll(dest, 0o700) }
        b, err := fs.ReadFile(files, name)
        if err != nil { return err }
        return os.WriteFile(dest, b, 0o600)
    }); err != nil { return "", err }
    if err := os.WriteFile(filepath.Join(stage, ".complete"), []byte(version+"\n"), 0o600); err != nil {
        return "", err
    }
    if err := os.Rename(stage, target); err != nil {
        // Another process may have published this exact immutable version.
        if _, statErr := os.Stat(filepath.Join(target, ".complete")); statErr == nil {
            return target, nil
        }
        return "", fmt.Errorf("publish bundled LM Detector: %w", err)
    }
    return target, nil
}
